<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { api,http } from '@/api/http'
import { useAuthStore } from '@/stores/auth'
import type { PageData } from '@/types'
import { ElMessage } from 'element-plus'
import { Refresh } from '@element-plus/icons-vue'
const auth=useAuthStore(),tab=ref('stock'),list=ref<any[]>([]),total=ref(0),page=ref(1),keyword=ref(''),lowOnly=ref(false),loading=ref(false),dialog=ref(false),mode=ref<'adjust'|'movement'>('adjust'),selected=ref<any>(),form=reactive({targetQty:0,quantity:1,direction:'IN',reason:''})
const canEdit=auth.can('ADMIN','INVENTORY_MANAGER')
async function load(){loading.value=true;try{if(tab.value==='stock'){const d=await api<PageData<any>>(http.get('/inventory',{params:{keyword:keyword.value,lowOnly:lowOnly.value,page:page.value,pageSize:15}}));list.value=d.items;total.value=d.total}else{const d=await api<PageData<any>>(http.get('/inventory/movements',{params:{page:page.value,pageSize:15}}));list.value=d.items;total.value=d.total}}finally{loading.value=false}}
function open(row:any,next:'adjust'|'movement'){selected.value=row;mode.value=next;form.targetQty=row.currentQty;form.quantity=1;form.direction='IN';form.reason='';dialog.value=true}
async function save(){if(!form.reason){ElMessage.warning('请填写变更原因');return}if(mode.value==='adjust')await api(http.post(`/inventory/${selected.value.productId}/adjust`,{targetQty:form.targetQty,reason:form.reason}));else await api(http.post(`/inventory/${selected.value.productId}/movement`,{quantity:form.quantity,direction:form.direction,reason:form.reason}));ElMessage.success('库存已更新并记录流水');dialog.value=false;load()}
onMounted(load)
</script>
<template><div><div class="page-head"><div><h2>库存中心</h2><p>当前库存为实物账面数；预占库存已被待付款订单锁定；可售库存为两者之差。</p></div><el-button :icon="Refresh" @click="load">刷新</el-button></div><div class="metric-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))"><article class="metric"><span class="label">当前库存</span><strong>实物账面</strong><small>采购入库、销售出库、退货回补改变</small></article><article class="metric"><span class="label">预占库存</span><strong>待付款锁定</strong><small>下单增加，取消或收款减少</small></article><article class="metric"><span class="label">可售库存</span><strong>当前 − 预占</strong><small>并发下单按此数量原子校验</small></article></div><section class="panel"><el-tabs v-model="tab" @tab-change="page=1;load()"><el-tab-pane label="库存台账" name="stock"/><el-tab-pane label="库存流水" name="movements"/></el-tabs><div v-if="tab==='stock'" class="toolbar"><el-input v-model="keyword" clearable placeholder="商品名称、编码或条码" style="width:300px" @keyup.enter="page=1;load()"/><el-checkbox v-model="lowOnly" @change="page=1;load()">仅看低库存</el-checkbox><el-button @click="page=1;load()">查询</el-button></div><el-table v-loading="loading" :data="list" stripe><template v-if="tab==='stock'"><el-table-column prop="code" label="商品编码" width="125"/><el-table-column prop="barcode" label="条码" width="150"/><el-table-column prop="name" label="商品" min-width="170"/><el-table-column prop="categoryName" label="分类" width="120"/><el-table-column prop="currentQty" label="当前" width="85"/><el-table-column prop="reservedQty" label="预占" width="85"/><el-table-column label="可售" width="85"><template #default="s"><strong :class="s.row.lowStock?'danger-text':'stock-ok'">{{ s.row.availableQty }}</strong></template></el-table-column><el-table-column prop="lowStockThreshold" label="预警阈值" width="100"/><el-table-column v-if="canEdit" label="操作" width="150" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row,'movement')">出入库</el-button><el-button link type="warning" @click="open(s.row,'adjust')">盘点</el-button></template></el-table-column></template><template v-else><el-table-column prop="createdAt" label="时间" min-width="170"/><el-table-column prop="productCode" label="商品编码" width="120"/><el-table-column prop="productName" label="商品" min-width="150"/><el-table-column prop="businessType" label="业务类型" width="130"/><el-table-column label="实物变化" width="100"><template #default="s"><span :class="s.row.changeQty<0?'danger-text':'stock-ok'">{{ s.row.changeQty>0?'+':'' }}{{ s.row.changeQty }}</span></template></el-table-column><el-table-column label="预占变化" width="100"><template #default="s">{{ s.row.changeReservedQty>0?'+':'' }}{{ s.row.changeReservedQty }}</template></el-table-column><el-table-column label="变化后" width="120"><template #default="s">{{ s.row.afterQty }} / 预占 {{ s.row.afterReservedQty }}</template></el-table-column><el-table-column prop="businessRef" label="业务来源" min-width="190"/><el-table-column prop="operatorName" label="操作人" width="110"/><el-table-column prop="remark" label="备注" min-width="200" show-overflow-tooltip/></template></el-table><el-pagination style="margin-top:18px;justify-content:flex-end" background layout="total,prev,pager,next" :total="total" :page-size="15" v-model:current-page="page" @current-change="load"/></section><el-dialog v-model="dialog" :title="mode==='adjust'?'库存盘点':'手工出入库'" width="460px"><p><strong>{{ selected?.name }}</strong> · 当前 {{ selected?.currentQty }} · 预占 {{ selected?.reservedQty }}</p><el-form label-position="top"><template v-if="mode==='adjust'"><el-form-item label="盘点后当前库存" required><el-input-number v-model="form.targetQty" :min="selected?.reservedQty||0" style="width:100%"/></el-form-item></template><template v-else><el-form-item label="方向"><el-radio-group v-model="form.direction"><el-radio-button value="IN">入库</el-radio-button><el-radio-button value="OUT">出库</el-radio-button></el-radio-group></el-form-item><el-form-item label="数量" required><el-input-number v-model="form.quantity" :min="1" style="width:100%"/></el-form-item></template><el-form-item label="原因" required><el-input v-model="form.reason" type="textarea" placeholder="将写入不可变更的库存流水"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">确认并记账</el-button></template></el-dialog></div></template>
